#!/usr/bin/env node
// Task-local replacement for scripts/email-contacts.js using only Node built-ins.
const fs = require('fs');
const path = require('path');

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';
const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

async function main() {
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL,
    },
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }

  const contacts = data.contacts || [];
  const lines = contacts.map((c) => {
    const name = c.name || '';
    const email = c.email || '';
    return email ? `${name} <${email}>`.trim() : name;
  });
  const outPath = path.join(process.cwd(), 'contacts.txt');
  fs.writeFileSync(outPath, lines.length ? lines.join('\n') + '\n' : '');

  console.log(JSON.stringify({ success: true, count: contacts.length, savedTo: outPath, contacts }, null, 2));
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local replica of .codex/skills/email-api/scripts/email-contacts.js
// (which cannot run here because its npm dependency 'minimist' is not installed).
// Uses only Node built-ins / globals. Same endpoint, headers, and output shape.

const BASE_URLS = [
  'https://agenskill-api.onrender.com', // skill manifest default
  'https://agenskill.onrender.com'      // helper script hardcoded fallback
];

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok === '--api-key') args.apiKey = argv[++i];
    else if (tok === '--user-email') args.userEmail = argv[++i];
  }
  return args;
}

async function getContacts(baseUrl, apiKey, userEmail) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch(`${baseUrl}/contacts`, {
      signal: controller.signal,
      headers: {
        'X-API-Key': apiKey,
        'X-User-Email': userEmail
      }
    });
    let data;
    try {
      data = await response.json();
    } catch (e) {
      data = {};
    }
    if (!response.ok) {
      throw new Error(`HTTP ${response.status} ${data.error || ''}`.trim());
    }
    return { response, data };
  } finally {
    clearTimeout(timer);
  }
}

async function main() {
  const { apiKey, userEmail } = parseArgs(process.argv.slice(2));
  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  let lastError = null;
  for (const baseUrl of BASE_URLS) {
    try {
      const { data } = await getContacts(baseUrl, apiKey, userEmail);
      const contacts = Array.isArray(data.contacts) ? data.contacts : [];
      console.log(JSON.stringify({
        success: true,
        baseUrl,
        count: contacts.length,
        contacts
      }, null, 2));
      return;
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error('Failed to get contacts');
}

main().catch(error => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

